573:         /// <inheritdoc/>
574:         public bool DoesBucketExist(string bucketName)
575:         {
576:             if (string.IsNullOrEmpty(bucketName))
577:                 throw new ArgumentException(Resources.ExceptionIfArgumentStringIsNullOrEmpty, "bucketName");
578:             if (!OssUtils.IsBucketNameValid(bucketName))
579:                 throw new ArgumentException(OssResources.BucketNameInvalid, "bucketName");
580: 
581:             try
582:             {
583:                 GetBucketAcl(bucketName);
584:             }
585:             catch (OssException e)
586:             {
587:                 if (e.ErrorCode.Equals(OssErrorCode.NoSuchBucket))
588:                     return false;
589:             }
590: 
591:             return true;
592:         }
