            public ResponseImpl(HttpResponseMessage httpWebResponse)
            {
                _response = httpWebResponse;
                try
                {
                    _stream = (_response.Content != null) ? _response.Content.ReadAsStreamAsync().Result : null;
                    if (!_response.IsSuccessStatusCode)
