240:         private static void SetRequestContent(HttpWebRequest webRequest, 
241:                                               ServiceRequest serviceRequest,
242:                                               ClientConfiguration clientConfiguration)
243:         {
244:             var data = serviceRequest.BuildRequestContent();
245: 
246:             if (data == null ||
247:                 (serviceRequest.Method != HttpMethod.Put &&
248:                  serviceRequest.Method != HttpMethod.Post))
249:             {
250:                 return;
251:             }
252: 
253:             // Write data to the request stream.
254:             long userSetContentLength = -1;
255:             if (serviceRequest.Headers.ContainsKey(HttpHeaders.ContentLength))
256:                 userSetContentLength = long.Parse(serviceRequest.Headers[HttpHeaders.ContentLength]);
257:             
258:             if (serviceRequest.UseChunkedEncoding || !data.CanSeek) // when data cannot seek, we have to use chunked encoding as there's no way to set the length
259:             {
260:                 webRequest.SendChunked = true;
261:                 webRequest.AllowWriteStreamBuffering = false; // when using chunked encoding, the data is likely big and thus not use write buffer;
262:             }
263:             else
264:             {
265:                 long streamLength = data.Length - data.Position;
266:                 webRequest.ContentLength = (userSetContentLength >= 0 &&
267:                     userSetContentLength <= streamLength) ? userSetContentLength : streamLength;
268:                 if (webRequest.ContentLength > clientConfiguration.DirectWriteStreamThreshold)
269:                 {
270:                     webRequest.AllowWriteStreamBuffering = false;
271:                 }
272:             }
273: 
274:             using (var requestStream = webRequest.GetRequestStream())
275:             {
276:                 if (!webRequest.SendChunked)
277:                 {
278:                     IoUtils.WriteTo(data, requestStream, webRequest.ContentLength);
279:                 }
280:                 else
281:                 {
282:                     IoUtils.WriteTo(data, requestStream);
283:                 }
284:             }
285:         }
