289:         {
290:             var data = serviceRequest.BuildRequestContent();
291: 
292:             if (data == null ||
293:                 (serviceRequest.Method != HttpMethod.Put &&
294:                  serviceRequest.Method != HttpMethod.Post))
295:             {
296:                 // Skip setting content body in this case.
297:                 try
298:                 {
299:                     asyncCallback();
300:                 }
301:                 catch(Exception e)
302:                 {
303:                     result.WebRequest.Abort();
304:                     result.Complete(e);
305:                 }
306: 
307:                 return;
308:             }
309: 
310:             // Write data to the request stream.
311:             long userSetContentLength = -1;
312:             if (serviceRequest.Headers.ContainsKey(HttpHeaders.ContentLength))
313:                 userSetContentLength = long.Parse(serviceRequest.Headers[HttpHeaders.ContentLength]);
314: 
315:             if (serviceRequest.UseChunkedEncoding || !data.CanSeek) // when data cannot seek, we have to use chunked encoding as there's no way to set the length
316:             {
317:                 webRequest.SendChunked = true;
318:                 webRequest.AllowWriteStreamBuffering = false; // when using chunked encoding, the data is likely big and thus not use write buffer;
319:             }
320:             else
321:             {
322:                 long streamLength = data.Length - data.Position;
323:                 webRequest.ContentLength = (userSetContentLength >= 0 &&
324:                     userSetContentLength <= streamLength) ? userSetContentLength : streamLength;
325:                 if (webRequest.ContentLength > clientConfiguration.DirectWriteStreamThreshold)
326:                 {
327:                     webRequest.AllowWriteStreamBuffering = false;
328:                 }
329:             }
330: 
331:             webRequest.BeginGetRequestStream(
332:                     (ar) =>
333:                     {
334:                         try
335:                         {
336:                             using (var requestStream = webRequest.EndGetRequestStream(ar))
337:                             {
338:                                 if (!webRequest.SendChunked)
339:                                 {
340:                                     IoUtils.WriteTo(data, requestStream, webRequest.ContentLength);
341:                                 }
342:                                 else
343:                                 {
344:                                     IoUtils.WriteTo(data, requestStream);
345:                                 }
346:                             }
347:                             asyncCallback();
348:                         }
349:                         catch(Exception e)
350:                         {
351:                             result.WebRequest.Abort();
352:                             result.Complete(e);
353:                         }
354:                     }, null);
