395:         // Set request headers
396:         private static void SetRequestHeaders(HttpWebRequest webRequest, ServiceRequest serviceRequest,
397:                                               ClientConfiguration configuration)
398:         {
399:             webRequest.Timeout = configuration.ConnectionTimeout;
400:             webRequest.ReadWriteTimeout = configuration.ConnectionTimeout;
401:             webRequest.Method = serviceRequest.Method.ToString().ToUpperInvariant();
402: 
403:             // Because it is not allowed to set common headers
404:             // with the WebHeaderCollection.Add method,
405:             // we have to call an internal method to skip validation.
406:             foreach (var h in serviceRequest.Headers)
407:             {
408:                 // Nginx does not accept a chunked encoding request with Content-Length, as detailed in #OSS-2848
409:                 if (h.Key.Equals(HttpHeaders.ContentLength) && (serviceRequest.UseChunkedEncoding || 
410:                     (serviceRequest.Content != null && !serviceRequest.Content.CanSeek) || serviceRequest.Content == null))
411:                 {
412:                     continue;
413:                 }
414: 
415:                 HttpExtensions.AddInternal(webRequest.Headers, h.Key, h.Value);
416:             }
417: 
418:             // Set user-agent
419:             if (!string.IsNullOrEmpty(configuration.UserAgent))
420:                 webRequest.UserAgent = configuration.UserAgent;
