432: 
433:             // Set proxy if proxy settings are specified.
434:             if (!string.IsNullOrEmpty(configuration.ProxyHost))
435:             {
436:                 if (configuration.ProxyPort < 0)
437:                     webRequest.Proxy = new WebProxy(configuration.ProxyHost);
438:                 else
439:                     webRequest.Proxy = new WebProxy(configuration.ProxyHost, configuration.ProxyPort);
440: 
441:                 if (!string.IsNullOrEmpty(configuration.ProxyUserName))
442:                 {
443:                     webRequest.Proxy.Credentials = String.IsNullOrEmpty(configuration.ProxyDomain) ?
444:                         new NetworkCredential(configuration.ProxyUserName, configuration.ProxyPassword ?? string.Empty) :
445:                         new NetworkCredential(configuration.ProxyUserName, configuration.ProxyPassword ?? string.Empty,
446:                                               configuration.ProxyDomain);
447:                 }
